/**
 * A token bucket. Tokens are tracked as an exact fraction, stored as an
 * integer numerator over the constant denominator `per`, so that partial
 * refill periods never lose precision.
 */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.state = new Map()
  }

  advance(key, tick) {
    const s = this.state.get(key)
    if (!s) {
      this.state.set(key, { numerator: this.capacity * this.per, lastTick: tick })
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      const cap = this.capacity * this.per
      let numerator = s.numerator + this.refill * elapsed
      if (numerator > cap) numerator = cap
      s.numerator = numerator
      s.lastTick = tick
    }
  }

  allowed(key) {
    return this.state.get(key).numerator >= this.per
  }

  record(key) {
    this.state.get(key).numerator -= this.per
  }
}

/**
 * A sliding window. Remembered ticks are held in an array with a live-range
 * start index so that forgetting old ticks is amortised O(1) per advance.
 */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      s = { ticks: [], start: 0 }
      this.state.set(key, s)
    }
    const threshold = tick - this.span
    while (s.start < s.ticks.length && s.ticks[s.start] <= threshold) s.start++
    if (s.start > 1024 && s.start * 2 > s.ticks.length) {
      s.ticks = s.ticks.slice(s.start)
      s.start = 0
    }
  }

