{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, or throws
 * a `LimiterError` naming the first line that fails to parse.
 */
import { LimiterError } from './errors.js'
import { Bucket, Window } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function parseField(token, field, least) {
  if (!INT_RE.test(token) || BigInt(token) < least) {
    throw new Error(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(token)
}

/**
 * Splits an input line into its whitespace-separated tokens, or returns
 * `null` when the line is blank or a comment.
 */
function tokenize(line) {
  const trimmed = line.trim()
  if (trimmed === '' || trimmed.startsWith('#')) return null
  return trimmed.split(/\s+/)
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const routeOrder = []
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const tokens = tokenize(lines[i])
    if (tokens === null) continue

    try {
      const directive = tokens[0]
      switch (directive) {
        case 'bucket': {
          if (seenEvent) throw new Error('declarations must come before the first event')
          if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
          const [, name, capacityTok, refillTok, perTok] = tokens
          if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
          if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
          const capacity = parseField(capacityTok, 'capacity', 1n)
          const refill = parseField(refillTok, 'refill', 0n)
          const per = parseField(perTok, 'per', 1n)
          policies.set(name, new Bucket(capacity, refill, per))
          break
        }
        case 'window': {
          if (seenEvent) throw new Error('declarations must come before the first event')
          if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
          const [, name, limitTok, spanTok] = tokens
          if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
          if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
          const limit = parseField(limitTok, 'limit', 0n)
          const span = parseField(spanTok, 'span', 1n)
          policies.set(name, new Window(limit, span))
          break
        }
        case 'route': {
          if (seenEvent) throw new Error('declarations must come before the first event')
          if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
          const [, prefix, ...policyNames] = tokens
          if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
          if (routes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
          for (const name of policyNames) {
            if (!policies.has(name)) throw new Error(`unknown policy ${name}`)
          }
          routes.set(prefix, policyNames)
          routeOrder.push(prefix)
          break
        }
        case 'event': {
          seenEvent = true
          if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
          const [, tickTok, key] = tokens
          const tick = parseField(tickTok, 'tick', 0n)
          if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
          if (lastTick !== null && tick < lastTick) {
            throw new Error(`tick ${tick} is before tick ${lastTick}`)
          }
          lastTick = tick
          events.push({ tick, key, line: lineNumber })
          break
        }
        default:
          throw new Error(`unknown directive ${directive}`)
      }
    } catch (err) {
      throw new LimiterError(lineNumber, err.message)
    }
  }

  return { policies, routes, routeOrder, events }
}
"}

