          if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
          if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
          const limit = parseField(limitTok, 'limit', 0n)
          const span = parseField(spanTok, 'span', 1n)
          policies.set(name, new Window(limit, span))
          break
        }
        case 'route': {
          if (seenEvent) throw new Error('declarations must come before the first event')
          if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
          const [, prefix, ...policyNames] = tokens
          if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
          if (routes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
          for (const name of policyNames) {
            if (!policies.has(name)) throw new Error(`unknown policy ${name}`)
          }
          routes.set(prefix, policyNames)
          routeOrder.push(prefix)
          break
        }
        case 'event': {
          seenEvent = true
          if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
          const [, tickTok, key] = tokens
          const tick = parseField(tickTok, 'tick', 0n)
          if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
          if (lastTick !== null && tick < lastTick) {
            throw new Error(`tick ${tick} is before tick ${lastTick}`)
          }
          lastTick = tick
          events.push({ tick, key, line: lineNumber })
          break
        }
        default:
          throw new Error(`unknown directive ${directive}`)
      }
    } catch (err) {
      throw new LimiterError(lineNumber, err.message)
    }
  }

  return { policies, routes, routeOrder, events }
}
"}

